-- Synthetic test schema, never use against a real clinic database.
CREATE TABLE persons (id BIGINT UNSIGNED PRIMARY KEY, status ENUM('ACTIVE','INACTIVE') NOT NULL DEFAULT 'ACTIVE') ENGINE=InnoDB;
CREATE TABLE service_types (id BIGINT UNSIGNED PRIMARY KEY, is_active TINYINT NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE role_assignments (id BIGINT UNSIGNED PRIMARY KEY, person_id BIGINT UNSIGNED NOT NULL, role_code VARCHAR(20) NOT NULL, status ENUM('ACTIVE','REVOKED') NOT NULL) ENGINE=InnoDB;
CREATE TABLE admissions (id BIGINT UNSIGNED PRIMARY KEY, patient_person_id BIGINT UNSIGNED NOT NULL) ENGINE=InnoDB;
CREATE TABLE booking_requests (id BIGINT UNSIGNED PRIMARY KEY, converted_admission_id BIGINT UNSIGNED NULL) ENGINE=InnoDB;
CREATE TABLE appointments (id BIGINT UNSIGNED PRIMARY KEY, admission_id BIGINT UNSIGNED NOT NULL, therapist_person_id BIGINT UNSIGNED NOT NULL, service_type_id BIGINT UNSIGNED NOT NULL, status ENUM('SCHEDULED','COMPLETED','CANCELLED','NO_SHOW') NOT NULL, rescheduled_from_id BIGINT UNSIGNED NULL, appointment_start_utc DATETIME NOT NULL, room_id BIGINT UNSIGNED NOT NULL, duration_minutes SMALLINT UNSIGNED NOT NULL) ENGINE=InnoDB;
CREATE TABLE finance_centers (id BIGINT UNSIGNED PRIMARY KEY, name VARCHAR(150) NOT NULL, status ENUM('ACTIVE','INACTIVE') NOT NULL, commission_model ENUM('HOURLY','PERCENTAGE') NOT NULL) ENGINE=InnoDB;
CREATE TABLE rooms (id BIGINT UNSIGNED PRIMARY KEY, center_id BIGINT UNSIGNED, hourly_rate DECIMAL(12,2)) ENGINE=InnoDB;
CREATE TABLE finance_center_settlements (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, public_id VARCHAR(30) NOT NULL UNIQUE, center_id BIGINT UNSIGNED NOT NULL, period_start DATE NOT NULL, period_end DATE NOT NULL, amount_due_rial DECIMAL(12,0) NOT NULL DEFAULT 0, recorded_by_person_id BIGINT UNSIGNED NULL, created_at DATETIME NOT NULL, UNIQUE KEY uq_test_period(center_id,period_start,period_end)) ENGINE=InnoDB;
CREATE TABLE finance_bank_accounts (id BIGINT UNSIGNED PRIMARY KEY, status ENUM('ACTIVE','INACTIVE') NOT NULL) ENGINE=InnoDB;
CREATE TABLE finance_session_payments (id BIGINT UNSIGNED PRIMARY KEY, appointment_id BIGINT UNSIGNED NOT NULL UNIQUE) ENGINE=InnoDB;
